-- Incluye 45 clientes sinteticos, 500 pedidos, detalle y trazabilidad.
-- Ejecutar despues de catalogo-avance3.sql.
USE autocr;

CREATE TABLE IF NOT EXISTS datos_migracion (
    id_migracion VARCHAR(80) NOT NULL,
    fecha_aplicacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id_migracion)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP PROCEDURE IF EXISTS cargar_pedidos_historicos_avance3;
DELIMITER $$
CREATE PROCEDURE cargar_pedidos_historicos_avance3()
BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    IF NOT EXISTS (
        SELECT 1 FROM datos_migracion
        WHERE id_migracion = 'avance3-pedidos-historicos-v1'
    ) THEN
        START TRANSACTION;

-- Clientes sinteticos adicionales para el historial de pedidos
-- Password de prueba para todos: Cliente123!
-- ---------------------------------------------------------

-- ---------------------------------------------------------
-- 500 pedidos historicos (ultimos 12 meses) para metricas y reportes
-- ---------------------------------------------------------




















        VALUES ('avance3-pedidos-historicos-v1');
        COMMIT;
    END IF;
END$$
DELIMITER ;

CALL cargar_pedidos_historicos_avance3();
DROP PROCEDURE cargar_pedidos_historicos_avance3;

